#include "intrinsic_queries.h"

#include <string.h>

#include "mmay/check/intrinsics.h"
#include "output.h"
#include "source_locations.h"

static const char lsp_intrinsic_path[] = "std/json/intrinsics.my";
static const char lsp_intrinsic_notice[] =
    "// Compiler intrinsic: interface/signature only; implementation generated by compiler.\n"
    "// This generated API reference is not a compilation input.\n\n";

LspStatus lsp_intrinsic_views_init(LspAnalysis *analysis) {
    LspOutput text;
    MarimayWriter writer;
    MarimaySourceStatus status = MMAY_SOURCE_OK;
    const MarimaySourceSnapshot *snapshot = NULL;
    const MarimayIntrinsicSignature *intrinsic = NULL;
    size_t index = 0;
    bool ok = true;
    if (analysis == NULL) return LSP_INVALID;
    if (analysis->intrinsic_sources_initialized
        || analysis->result.checked.intrinsic_calls.length == 0) return LSP_OK;
    if (!lsp_output_init(&text, analysis->target.allocator)) return LSP_ALLOCATION_FAILED;
    writer = lsp_output_writer(&text);
    ok = mmay_writer_write_cstr(writer, lsp_intrinsic_notice);
    for (index = 0; ok && (intrinsic = mmay_intrinsic_signature(index)) != NULL; index += 1) {
        ok = mmay_writer_write_cstr(writer, "// ")
            && mmay_writer_write_cstr(writer, intrinsic->constraint)
            && mmay_writer_write_cstr(writer, "\n")
            && mmay_writer_write_cstr(writer, intrinsic->signature)
            && mmay_writer_write_cstr(writer, ";\n\n");
    }
    if (ok) {
        ok = mmay_source_manager_init(&analysis->intrinsic_sources, analysis->target.allocator);
        analysis->intrinsic_sources_initialized = ok;
        if (ok) status = mmay_source_manager_add(&analysis->intrinsic_sources,
            lsp_intrinsic_path, sizeof(lsp_intrinsic_path) - 1,
            text.bytes.data, text.bytes.length, &snapshot);
    }
    lsp_output_dispose(&text);
    if (!ok || status != MMAY_SOURCE_OK) {
        if (analysis->intrinsic_sources_initialized)
            mmay_source_manager_dispose(&analysis->intrinsic_sources);
        analysis->intrinsic_sources_initialized = false;
        return LSP_ALLOCATION_FAILED;
    }
    return LSP_OK;
}

static const MarimaySourceSnapshot *lsp_intrinsic_view(const LspAnalysis *analysis) {
    if (!analysis->intrinsic_sources_initialized) return NULL;
    return mmay_source_manager_current(&analysis->intrinsic_sources, 1);
}

static bool lsp_intrinsic_span(const MarimaySourceSnapshot *snapshot,
    const MarimayIntrinsicSignature *intrinsic, size_t *start, size_t *end) {
    const unsigned char *bytes;
    size_t length, offset = 0;
    size_t signature_length = strlen(intrinsic->signature);
    if (snapshot == NULL) return false;
    bytes = mmay_source_bytes(snapshot);
    length = mmay_source_length(snapshot);
    if (signature_length > length
        || strncmp(intrinsic->signature, "fn ", 3) != 0) return false;
    for (offset = 0; offset <= length - signature_length; offset += 1) {
        if ((offset == 0 || bytes[offset - 1] == '\n')
            && memcmp(bytes + offset, intrinsic->signature, signature_length) == 0) {
            *start = offset + 3;
            *end = *start + strlen(intrinsic->name);
            return true;
        }
    }
    return false;
}

static const MarimayIntrinsicSignature *lsp_intrinsic_at(const LspAnalysis *analysis,
    const MarimaySourceSnapshot *snapshot, size_t offset) {
    const MarimayCheckedIntrinsicCall *call = mmay_checked_intrinsic_call_at(
        &analysis->result.checked, snapshot, offset);
    if (call == NULL && offset != 0) {
        const MarimayCheckedIntrinsicCall *previous = mmay_checked_intrinsic_call_at(
            &analysis->result.checked, snapshot, offset - 1);
        if (previous != NULL && previous->end == offset) call = previous;
    }
    if (call != NULL) return call->intrinsic;
    if (snapshot == lsp_intrinsic_view(analysis)) {
        const MarimayIntrinsicSignature *intrinsic = NULL;
        size_t index = 0, start = 0, end = 0;
        for (index = 0; (intrinsic = mmay_intrinsic_signature(index)) != NULL; index += 1)
            if (lsp_intrinsic_span(snapshot, intrinsic, &start, &end)
                && start <= offset && offset <= end) return intrinsic;
    }
    return NULL;
}

static bool lsp_intrinsic_hover(MarimayWriter writer, MarimayAllocator allocator,
    const MarimayIntrinsicSignature *intrinsic) {
    LspOutput value;
    bool ok = lsp_output_init(&value, allocator);
    MarimayWriter text = lsp_output_writer(&value);
    if (ok) ok = mmay_writer_write_cstr(text, lsp_intrinsic_notice)
        && mmay_writer_write_cstr(text, intrinsic->signature)
        && mmay_writer_write_cstr(text, "\n// ")
        && mmay_writer_write_cstr(text, intrinsic->constraint)
        && mmay_writer_write_cstr(writer, "{\"contents\":{\"language\":\"marimay\",\"value\":")
        && mmay_lsp_json_write_string(writer, value.bytes.data, value.bytes.length)
        && mmay_writer_write_cstr(writer, "}}");
    lsp_output_dispose(&value);
    return ok;
}

static bool lsp_intrinsic_references(const LspAnalysis *analysis,
    const MarimayIntrinsicSignature *intrinsic, const MarimaySourceSnapshot *view,
    size_t start, size_t end, bool include_declaration, MarimayWriter writer) {
    size_t index = 0;
    bool first = true;
    if (!mmay_writer_write_cstr(writer, "[")) return false;
    if (include_declaration) {
        if (!lsp_source_write_location(writer, analysis, view, start, end)) return false;
        first = false;
    }
    for (index = 0; index < analysis->result.checked.intrinsic_calls.length; index += 1) {
        const MarimayCheckedIntrinsicCall *call = mmay_checked_intrinsic_call(
            &analysis->result.checked, index);
        if (call == NULL || call->intrinsic != intrinsic) continue;
        if ((!first && !mmay_writer_write_cstr(writer, ","))
            || !lsp_source_write_location(writer, analysis, call->snapshot,
                call->start, call->end)) return false;
        first = false;
    }
    return mmay_writer_write_cstr(writer, "]");
}

bool lsp_intrinsic_query(const LspAnalysis *analysis,
    const MarimaySourceSnapshot *snapshot, size_t offset,
    LspIntrinsicQueryKind kind, bool include_declaration,
    MarimayWriter writer, bool *found) {
    const MarimayIntrinsicSignature *intrinsic = NULL;
    const MarimaySourceSnapshot *view = NULL;
    size_t start = 0, end = 0;
    *found = false;
    if (analysis == NULL || snapshot == NULL) return true;
    intrinsic = lsp_intrinsic_at(analysis, snapshot, offset);
    if (intrinsic == NULL) return true;
    *found = true;
    if (kind == LSP_INTRINSIC_HOVER)
        return lsp_intrinsic_hover(writer, analysis->target.allocator, intrinsic);
    view = lsp_intrinsic_view(analysis);
    if (view == NULL || !lsp_intrinsic_span(view, intrinsic, &start, &end)) return false;
    if (kind == LSP_INTRINSIC_DEFINITION)
        return lsp_source_write_location(writer, analysis, view, start, end);
    return lsp_intrinsic_references(analysis, intrinsic, view, start, end,
        include_declaration, writer);
}
